param([ValidateSet('x86', 'x64')][string]$Platform)
$ErrorActionPreference = 'Stop'
if (!$Platform) {
  foreach ($arch in @('x86', 'x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -Platform $arch
    if ($LASTEXITCODE -ne 0) { throw "Data diagnostics test failed for $arch" }
  }
  exit 0
}
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = Join-Path $repoRoot '.deps/dxvk-remix'
. (Join-Path $source 'bridge/build_common.ps1')
SetupVS -Platform $Platform -VcVarsVer '14.29'
$output = Join-Path $repoRoot ".deps/data-test-$Platform"
New-Item -ItemType Directory -Force $output | Out-Null
Push-Location $output
try {
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /DNOMINMAX "/I$source/bridge/src/util" "$repoRoot/tests/data_diagnostics_test.cpp" "$source/bridge/src/util/data_diagnostics.cpp" /Fe:data-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Data test compilation failed' }
  foreach ($mode in @('--disabled', 'normal', '--overflow', '--cap', '--periodic')) {
    & .\data-test.exe $mode
    if ($LASTEXITCODE -ne 0) { throw "Data test $mode failed" }
  }
} finally { Pop-Location }
